1	// Tập 7 · C4 · TIỆN ÍCH CHUNG cho bảy đoạn thế giới của tập (world/c4/<đoạn>/scene.js). Không đổi thư viện nhà máy (lib3d.js / core.js).
2	// Gốc: world/c3kit.js (Tessa + nhà, the stack, nhãn, lớp bắt buộc — C3 đã duyệt) + phần mới của C4: Tessa CỬ ĐỘNG (tay + nghiêng người, hàng chờ C4
3	// gates/C3.md §3 #1), vật khoản vay riêng gắn với nhà (LoanTag, S01), thẻ hai khoản (V4 adapted, S02–S03), dải tuần (V1 xem trước, S02), lớp bắt buộc
4	// có đối trọng, cảnh khung cho đoạn chưa dựng. Mốc giờ CHỈ từ spine.json của đoạn; hằng số ở đây = hình học + độ dài hiệu ứng chung.
5	import * as THREE from 'three';
6	import { Studio, Stack, setOpacity, PALETTE } from '/toolkit/factory/world/lib3d.js';
7	import { Camera, Stage, loadJSON, fonts, C, ease, lin, mix, rgba } from '/toolkit/factory/world/core.js';
8	import { home, nameTag, theStack, stackSet, BUNDLE_TH, label, brace, modeLook, FIG } from '/episodes/ep007/world/c3kit.js';
9	
10	export const POP = 0.2, PLATE = '#0B0E13';
11	// màu nhận diện (không mang nghĩa dữ liệu) — contract.json characters: Tessa = PALETTE.person2 (C3), Leo = PALETTE.person1
12	export const CHAR = { tessa: FIG, leo: PALETTE.person1 };
13	export const kf = (k, t) => { if (!k || !k.length) return 0; if (t <= k[0][0]) return k[0][1];
14	  for (let i = 1; i < k.length; i++) if (t <= k[i][0]) { const [a, x] = k[i - 1], [b, y] = k[i]; return b > a ? x + (y - x) * (t - a) / (b - a) : y; }
15	  return k[k.length - 1][1]; };
16	// hiện từ mốc a (dốc POP), tắt từ mốc z (dốc 0,3 s) nếu có
17	export const show = (t, a, z = Infinity) => (a == null ? 0 : ease(t, a - 0.05, a + POP) * (1 - ease(t, z, z + 0.3)));
18	export const pulse = (t, a, d = 0.6) => (a == null || t < a ? 0 : Math.max(0, 1 - (t - a) / d));
19	
20	export async function setup(seg, res, poses, { shadowBox = 16 } = {}) {
21	  const [S, CL] = await Promise.all([loadJSON(seg + 'spine.json'), loadJSON('/episodes/ep007/world/claims.json')]);
22	  await fonts();
23	  const cue = {}; for (const b of S.beats) cue[b.id] = { ...b.cues, t0: b.t0, t1: b.t1 };
24	  const MV = {}; for (const m of S.moves) MV[m.id] = m;
25	  const st = Stage(res), scene = new THREE.Scene(), { floor, key } = Studio(scene, { shadowBox });
26	  const D = (k) => CL[k].display;
27	  return { S, CL, D, G: CL._geom, cue, MV, st, O: st.O, renderer: st.renderer, scene, floor, key, CAM: Camera(poses, S.moves) };
28	}
29	// đèn chính theo điểm nhìn (bóng có ở mọi khu của đoạn dài)
30	export function followLight(key, tgt) {
31	  key.target.position.set(tgt[0], Math.max(0, tgt[1]), tgt[2]); key.position.set(tgt[0] - 6, Math.max(0, tgt[1]) + 14, tgt[2] + 10); key.target.updateMatrixWorld();
32	}
33	
34	// ================================================================ Tessa có cử động (hàng chờ C4 #1: "đứng yên cả 5 đoạn ở chế độ đồ thị")
35	// Người W4 tròn xoay → quay đầu không thấy được từ chính diện. Cử động đọc được ở máy chính diện: (1) NGHIÊNG người về phía vật (xoay quanh trục
36	// nhìn), (2) GIƠ TAY (cánh tay viên nang cùng màu, buông dọc thân lúc nghỉ) về phía vật, (3) gật nhẹ (đầu hạ 0,03). Mỗi cử động = một sự kiện
37	// {t, kind: 'arm'|'lean'|'nod', to: x thế giới của vật, hold} trong spine (S.gestures) — đúng lúc vật chạm/dâng.
38	export function figure(scene, opts) {
39	  const hm = home(scene, opts), p = hm.person, h = hm.h;
40	  const body = p.children[0], head = p.children[1], m = body.material;
41	  const pivot = new THREE.Group(); pivot.position.set(0, h * 0.66, 0); p.add(pivot);
42	  const arm = new THREE.Mesh(new THREE.CapsuleGeometry(h * 0.045, h * 0.3, 4, 8), m); arm.position.y = -(h * 0.15 + h * 0.045); arm.castShadow = true; pivot.add(arm);
43	  hm.pivot = pivot; hm.head = head; hm.headY = head.position.y; hm.body = body;
44	  // cánh tay nghỉ: sát thân về phía vật gần nhất (bên phải nếu không có sự kiện)
45	  pivot.position.x = h * 0.17;
46	  return hm;
47	}
48	export function gesture(hm, t, G = []) {
49	  let lean = 0, arm = 0, nod = 0, side = 1;
50	  for (const g of G) {
51	    const a = ease(t, g.t - 0.12, g.t + 0.28) * (1 - ease(t, g.t + (g.hold ?? 1.2), g.t + (g.hold ?? 1.2) + 0.45));
52	    if (a <= 0) continue;
53	    const s = Math.sign((g.to ?? hm.person.position.x + 1) - hm.person.position.x) || 1;
54	    if (g.kind === 'arm') { if (a > arm) { arm = a; side = s; } lean = Math.max(lean, 0.35 * a); }
55	    else if (g.kind === 'lean') { if (a > lean) side = s; lean = Math.max(lean, a); }
56	    else nod = Math.max(nod, a);
57	  }
58	  const p = hm.person, h = hm.h;
59	  p.rotation.z = -side * 0.16 * lean;
60	  hm.pivot.position.x = side * h * 0.17;
61	  hm.pivot.rotation.z = side * (0.1 + 2.25 * arm);          // buông (0,1 rad ra ngoài) → giơ chéo lên về phía vật
62	  hm.head.position.y = hm.headY - 0.035 * Math.sin(Math.PI * Math.min(1, nod * 1.0));
63	}
64	
65	// tên dưới chân Tessa chỉ khi người trong khung (c3kit.nameTag kẹp tâm x ≥ 330: người ngoài khung vẫn có tên ở mép → sai chỗ)
66	export function figTag(O, hm, a = 1) {
67	  const [x] = O.toScreen(hm.person.position.x, 0.5, hm.person.position.z), v = Math.min(1, Math.max(0, Math.min(x - 40, 1880 - x) / 80));
68	  return nameTag(O, hm, a * v);
69	}
70	
71	// ================================================================ khoản vay $320,000 = VẬT RIÊNG gắn với nhà (hàng chờ C4 #2: chồng đọc thành "the loan is $720")
72	// Tấm giấy vay (khung ink-muted = vật cố định, mặt sáng, hai dòng chữ giả) trên cột ngắn trước góc phải nhà — cùng nhóm với nhà, không giống bó tiền
73	export function LoanTag(scene, hm) {
74	  const g = new THREE.Group(), w = hm.w;
75	  const mat = (c, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.8, transparent: true, ...o });
76	  const post = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.62, 0.05), mat('#8C93A0')); post.position.y = 0.31;
77	  const plate = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.36, 0.03), mat('#E6E9EE', { emissive: new THREE.Color('#E6E9EE'), emissiveIntensity: 0.15 })); plate.position.y = 0.74;
78	  const rim = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.42, 0.02), mat(C.muted)); rim.position.set(0, 0.74, -0.012);
79	  const lines = [0.08, 0, -0.08].map((dy, i) => { const l = new THREE.Mesh(new THREE.BoxGeometry(i === 2 ? 0.22 : 0.36, 0.022, 0.01), mat('#5B6573')); l.position.set(i === 2 ? -0.07 : 0, 0.74 + dy, 0.02); return l; });
80	  for (const m of [post, plate, rim, ...lines]) { m.castShadow = true; g.add(m); }
81	  g.position.set(hm.house.position.x + w * 0.5 + 0.12, 0, hm.house.position.z + w * 0.36 + 0.25); scene.add(g);
82	  g.userData.checks = { role: 'mark', key: 'loan-tag', series: 'principal' };
83	  g.set = (a) => { setOpacity(g, a); g.scale.setScalar(Math.max(0.001, 0.6 + 0.4 * a)); };
84	  g.top = () => [g.position.x, 0.95, g.position.z];
85	  g.set(0);
86	  return g;
87	}
88	
89	// ================================================================ V4 adapted: thẻ hai khoản vay (B02–B03, B33) — mặt tối viền ink-muted, chữ ở lớp phủ (đồ thị)
90	export function OfferCard(scene, { x, y, z = 0, w = 1.7, h = 0.66 } = {}) {
91	  const g = new THREE.Group();
92	  const face = new THREE.Mesh(new THREE.BoxGeometry(w, h, 0.04), new THREE.MeshStandardMaterial({ color: '#1A1F28', roughness: 0.6, transparent: true }));
93	  const rim = new THREE.Mesh(new THREE.BoxGeometry(w + 0.06, h + 0.06, 0.03), new THREE.MeshStandardMaterial({ color: C.muted, emissive: new THREE.Color(C.muted), emissiveIntensity: 0.3, transparent: true }));
94	  rim.position.z = -0.02;
95	  const band = new THREE.Mesh(new THREE.BoxGeometry(w, 0.09, 0.05), new THREE.MeshStandardMaterial({ color: C.cushion, emissive: new THREE.Color(C.cushion), emissiveIntensity: 0.5, transparent: true }));
96	  band.position.set(0, -h / 2 + 0.07, 0.01);
97	  g.add(rim, face, band); g.position.set(x, y, z); scene.add(g);
98	  g.userData.checks = { role: 'mark', key: 'offer-card' };
99	  g.set = ({ a = 1, band: b = 0 } = {}) => { setOpacity(g, a); band.visible = a > 0.01 && b > 0.01; band.scale.x = Math.max(0.001, b); band.material.opacity = a; g.scale.setScalar(Math.max(0.001, 0.7 + 0.3 * a)); };
100	  g.w = w; g.h = h;
101	  g.set({ a: 0 });
102	  return g;
103	}
104	
105	// ================================================================ V1 xem trước (B02): dải tuần — 1.833 ô, trái → phải = Aug 1991 → Oct 2026, nằm sau nhà.
106	// set({grow, rise, values, lastA}): grow ∈ [0,1] ô hiện trái → phải (ink-muted, mỏng); rise ∈ [0,1] mỗi ô mọc thành cột theo giá của đường lui tuần
107	// đó (warn, thang hình riêng); ô cuối = tuần của Tessa, sáng (lastA).
108	export function WeekStrip(scene, values, { x0 = -9, width = 15, z = -3.2, depth = 0.5, tileH = 0.05, unit = 2.6 / 30000 } = {}) {
109	  const n = values.length, pitch = width / n;
110	  const geo = new THREE.BoxGeometry(pitch * 0.92, 1, depth); geo.translate(0, 0.5, 0);
111	  const mesh = new THREE.InstancedMesh(geo, new THREE.MeshStandardMaterial({ roughness: 0.8, transparent: true, emissive: new THREE.Color('#000000') }), n);
112	  mesh.frustumCulled = false; mesh.castShadow = true; mesh.receiveShadow = true; scene.add(mesh);
113	  const M4 = new THREE.Matrix4(), col = new THREE.Color(), cM = new THREE.Color(C.muted), cW = new THREE.Color(C.warn), cI = new THREE.Color(C.ink), hide = new THREE.Matrix4().makeScale(0, 0, 0);
114	  for (let i = 0; i < n; i++) mesh.setColorAt(i, cM);
115	  mesh.userData.checks = { role: 'series', key: 'week-strip', series: 'weeks' };
116	  const api = { mesh, n, pitch, x0, z, xOf: (i) => x0 + (i + 0.5) * pitch,
117	    set({ grow = 1, rise = 0, lastA = 0, a = 1 } = {}) {
118	      const L = grow * (n + 120);
119	      for (let i = 0; i < n; i++) {
120	        const g = Math.min(1, Math.max(0, (L - i) / 120));
121	        if (g <= 0.001) { mesh.setMatrixAt(i, hide); continue; }
122	        const r = Math.min(1, Math.max(0, rise * 1.25 - 0.25 * i / n));
123	        const hgt = Math.max(0.001, mix(tileH, values[i] * unit, r) * g);
124	        M4.makeScale(1, hgt, 1).setPosition(api.xOf(i), 0, z); mesh.setMatrixAt(i, M4);
125	        col.copy(cM).lerp(cW, r); if (i === n - 1) col.lerp(cI, lastA);
126	        mesh.setColorAt(i, col);
127	      }
128	      mesh.instanceMatrix.needsUpdate = true; mesh.instanceColor.needsUpdate = true;
129	      mesh.material.opacity = a; mesh.visible = a > 0.005;
130	    } };
131	  api.set({ grow: 0 });
132	  return api;
133	}
134	
135	// ================================================================ W2 tháp bó (S08–S09): ĐÚNG bó của the stack (mệnh giá cố định G.bundle_usd, dày BUNDLE_TH, cỡ 0,9 × 0,6),
136	// xếp mỗi tầng cols × rows bó → tổng lãi hàng trăm nghìn đô la vẫn vừa khung thường; phần trên cùng (warnFrom) tô warn; bó ≥ hideFrom không vẽ (đang
137	// bay). Gốc = tâm đáy. set({count (bó, thực), warnFrom, hideFrom, a}); posOf(k) = tâm bó k (thế giới); topY(count) = đỉnh tầng cao nhất
138	export function BundleTower(scene, { x, z = 0, n, cols = 3, rows = 3, bw = 0.9, bd = 0.6, gap = 0.04, name = 'tower' } = {}) {
139	  const cap = Math.ceil(n) + 1, th = BUNDLE_TH, per = cols * rows;
140	  const geo = new THREE.BoxGeometry(bw, th * 0.92, bd), mesh = new THREE.InstancedMesh(geo, new THREE.MeshStandardMaterial({ roughness: 0.8, transparent: true }), cap);
141	  const strap = new THREE.InstancedMesh(new THREE.BoxGeometry(bw * 0.16, th * 0.94, bd * 1.02), new THREE.MeshStandardMaterial({ color: PALETTE.strap, roughness: 0.85, transparent: true }), cap);
142	  const g = new THREE.Group(); g.add(mesh, strap); g.position.set(x, 0, z); scene.add(g);
143	  mesh.castShadow = mesh.receiveShadow = true; mesh.frustumCulled = strap.frustumCulled = false;
144	  const M4 = new THREE.Matrix4(), col = new THREE.Color(), hide = new THREE.Matrix4().makeScale(0, 0, 0);
145	  for (let k = 0; k < cap; k++) mesh.setColorAt(k, col.set(PALETTE.bill));
146	  const local = (k) => { const L = Math.floor(k / per), c = k % per; return [(c % cols - (cols - 1) / 2) * (bw + gap), L * th + th / 2, (Math.floor(c / cols) - (rows - 1) / 2) * (bd + gap)]; };
147	  g.userData.checks = { role: 'bar', series: name, key: `tower-${name}` };
148	  g.set = ({ count = 0, warnFrom = Infinity, hideFrom = Infinity, a = 1 } = {}) => {
149	    for (let k = 0; k < cap; k++) {
150	      const frac = Math.min(1, Math.max(0, count - k));
151	      if (frac <= 0.001 || k >= hideFrom) { mesh.setMatrixAt(k, hide); strap.setMatrixAt(k, hide); continue; }
152	      const [lx, ly, lz] = local(k);
153	      M4.makeScale(1, frac, 1).setPosition(lx, ly - th * (1 - frac) / 2, lz); mesh.setMatrixAt(k, M4); strap.setMatrixAt(k, M4);
154	      mesh.setColorAt(k, col.set(k >= warnFrom ? PALETTE.warn : Math.floor(k / per) % 2 ? PALETTE.bill : PALETTE.bill2));
155	    }
156	    mesh.instanceMatrix.needsUpdate = strap.instanceMatrix.needsUpdate = true; mesh.instanceColor.needsUpdate = true;
157	    mesh.material.opacity = strap.material.opacity = a; g.visible = a > 0.005 && count > 0.001;
158	    g.userData.checks.value = +count.toFixed(2);
159	  };
160	  g.posOf = (k) => { const [lx, ly, lz] = local(k); return [x + lx, ly, z + lz]; };
161	  g.topY = (count) => (Math.floor(Math.max(0, count - 1e-6) / per) + 1) * th;
162	  g.halfW = (cols * (bw + gap) - gap) / 2;
163	  g.set({ count: 0 });
164	  return g;
165	}
166	
167	// ================================================================ lớp bắt buộc: ILLUSTRATIVE (mọi khung có Tessa/Leo) + nguồn + "US only · history, not a forecast"
168	// (mọi khung: mọi số của tập là lãi khảo sát đã qua) + đối trọng (cw) dòng trên history khi có
169	export const SRC = 'Freddie Mac weekly mortgage survey';
170	export function chrome(O, { illus = 1, cw = null, cwA = 1 } = {}) {
171	  O.chrome({ illus: illus > 0.01, illusA: illus, src: SRC, hist: true, ...(cw && cwA > 0.01 ? { cw, cwA } : {}) });
172	}
173	// đoạn thẳng lớp phủ (nét có ghi log.lines cho F-2)
174	export function seg2(O, x0, y0, x1, y1, color, a, lw = 4, dash = null) {
175	  if (a <= 0.01) return; const c = O.ctx; c.save(); c.globalAlpha = a; c.strokeStyle = color; c.lineWidth = lw; if (dash) c.setLineDash(dash);
176	  c.beginPath(); c.moveTo(x0, y0); c.lineTo(x1, y1); c.stroke(); c.restore();
177	}
178	// ngoặc đứng (V6, nét lớp phủ): x, y0 (trên) → y1 (dưới), chân hướng trái (tick > 0 = về phía vật bên trái)
179	export function vbrace(O, x, y0, y1, color, a, lw = 6, tick = 16) {
180	  if (a <= 0.01) return; const c = O.ctx; c.save(); c.globalAlpha = a; c.strokeStyle = color; c.lineWidth = lw;
181	  c.beginPath(); c.moveTo(x - tick, y0); c.lineTo(x, y0); c.lineTo(x, y1); c.lineTo(x - tick, y1); c.stroke(); c.restore();
182	}
183	// mở/kết đoạn: phủ nền tối dần (ranh giới đoạn; ident ở đoạn a). Vẽ TRƯỚC mọi chữ (chữ giữ tương phản)
184	export function dip(O, a) { if (a <= 0.005) return; const c = O.ctx; c.save(); c.globalAlpha = a; c.fillStyle = C.bg; c.fillRect(0, 0, 1920, 1080); c.restore(); }
185	
186	// ================================================================ cảnh KHUNG cho đoạn chưa dựng (lượt 2): Tessa + nhà đứng yên, lớp bắt buộc
187	export async function stubScene(seg, res) {
188	  const poses = { w: { pos: [-3.4, 2.2, 7.6], tgt: [-0.6, 0.8, 0], fov: 35, chart: 0 } };
189	  const { S, st, O, renderer, scene, floor, CAM } = await setup(seg, res, poses);
190	  const hm = figure(scene, { x: 0 });
191	  function frame(t) {
192	    const pose = CAM.apply(t), cam = CAM.cam; modeLook(scene, floor, pose.chart); gesture(hm, t, S.gestures || []);
193	    renderer.render(scene, cam);
194	    const log = O.begin(t, pose.chart, cam); log.roi = {};
195	    figTag(O, hm); chrome(O);
196	    st.compose(); log.camMoving = CAM.moving(t); return log;
197	  }
198	  return { canvas: st.out, frame };
199	}
200	
201	export { C, ease, lin, mix, rgba, THREE, Stack, setOpacity, PALETTE, home, nameTag, theStack, stackSet, BUNDLE_TH, label, brace, modeLook, FIG };
202

