31	// kẹp tâm x ≥ 330 (cả dòng trong khung) và đường chân chữ ≤ 880 (trên dòng "US only …" khi máy di chuyển)
32	export function nameTag(O, hm, a = 1, o = {}) {
33	  const [fx, fy] = O.toScreen(hm.person.position.x, 0, hm.person.position.z);
34	  return label(O, 'Tessa · ILLUSTRATIVE', Math.max(330, fx + (o.dx || 0)), Math.min(880, fy + 50 + (o.dy || 0)), { align: o.align || 'center', kind: 'name', px: 48, w: 600, alpha: a, char: 'Tessa' });
