37	// the stack (W2): bó mệnh giá CỐ ĐỊNH = một năm của khoản dự phòng (extra_vs15_total_now / 15 ≈ 12 × $120); 15 bó = $21,622.
38	// Bó = warn (beats.md Colour roles: "warn = the price of the fallback (the stack's bills)").
39	export const BUNDLE_TH = 0.17;
40	export function theStack(scene, G, { x, z = 0 }) {
41	  const s = Stack({ unitUsd: G.bundle_usd / BUNDLE_TH, bundleUsd: G.bundle_usd, w: 0.9, d: 0.6, maxUsd: G.stack_total * 1.05 });
42	  s.position.set(x, 0, z); scene.add(s); s.userData.checks = { role: 'bar', series: 'stack', key: 'the-stack' };
