46	
47	// N1 đường tháng chạy từ nhà Tessa (s21-track, s23-track dùng chung hình học + tư thế máy): nhà bên trái, cột-năm nối nhau sang phải,
48	// tháng 1 ở mép trước. Đồ thị = nhìn gần thẳng xuống mặt lưới (nghiêng 19°, tiêu cự dài) → lưới đọc như lịch 15 cột × 12 ô.
49	export const TRACK_POSES = {
50	  wT0: { pos: [-5.2, 3.4, 7.0], tgt: [1.7, 0, -1.8], fov: 40, chart: 0 },   // vòng 3: lệch trái 0,7 → Tessa (trái nhà) + tên trong khung
