61	// chế độ đồ thị: sàn + sương lùi đi (như Tập 5/6)
62	export function modeLook(scene, floor, cw) { floor.material.opacity = 1 - 0.85 * cw; scene.fog.near = 30 + 120 * cw; scene.fog.far = 80 + 220 * cw; }
