66	
67	// ngoặc ngang (nét lớp phủ, toạ độ thiết kế); tick > 0 = chân xuống, < 0 = chân lên
68	export function brace(O, x0, x1, y, color, a, lw = 5, tick = 14) {
69	  if (a <= 0.01) return; const c = O.ctx; c.save(); c.globalAlpha = a; c.strokeStyle = color; c.lineWidth = lw;
70	  c.beginPath(); c.moveTo(x0, y + tick); c.lineTo(x0, y); c.lineTo(x1, y); c.lineTo(x1, y + tick); c.stroke(); c.restore();
71	}
72	export function label(O, s, x, y, o = {}) { return O.text(s, x, y, o.px || 52, { plate: PLATE, plateA: 0.72, ...o }); }
73	export { C, THREE, setOpacity, ease };
