1	// Tập 7 · C3 · s25-bar (B25, KEY-10) · the bar: tờ đô la trả thêm rời tay Tessa; thanh (W3, ink-muted) trồi lên từ sàn ngay dưới tờ đô la rồi dâng
2	// tới độ cao lãi khoản vay → đồ thị: "the bar: 7.40% a year, before taxes"; vòng 3: tờ thứ hai "any other use" là BÓNG nét đứt đứng TÁCH khỏi
3	// đầu thanh, lên xuống nhẹ quanh độ cao thanh, không dừng trên hay dưới (độ cao để mở); "not tested: how any investment compares, …".
4	import { setup, home, nameTag, modeLook, chrome, label, kf, show, ease, setOpacity } from '/episodes/ep007/world/c3kit.js';
5	import { Beam } from '/toolkit/factory/world/lib3d.js';
6	import { Bill } from '/episodes/ep007/world/obj7.js';
7	
8	const SEG = '/episodes/ep007/world/c3/s25-bar/';
9	const PER_PCT = 0.3, BX = 0.6, BL = 3.0;   // độ cao thế giới mỗi điểm % lãi; tâm và chiều dài thanh
10	const GX = BX + BL / 2 + 1.2, BOB = 0.32, BOB_T = 2.6;   // bóng đô la thứ hai: tách đầu thanh 1,2; biên độ / chu kỳ lên xuống
11	
12	export async function boot(res) {
13	  const poses = {
14	    wB: { pos: [-4.6, 2.5, 7.6], tgt: [-0.4, 1.0, 0], fov: 38, chart: 0 },
15	    cB: { pos: [0.1, 1.45, 18], tgt: [0.1, 1.45, 0], fov: 19, chart: 1 },
16	  };
17	  const { S, D, cue, st, O, renderer, scene, floor, CAM } = await setup(SEG, res, poses);
18	  const b = cue, hm = home(scene, { x: -2.3 });
19	  const beam = Beam({ length: BL }); beam.scale.set(1, 2.2, 1.4); scene.add(beam); beam.userData.checks = { role: 'mark', series: 'bar', key: 'the-bar' };
20	  const d1 = Bill({ name: 'extra-dollar' }), d2 = Bill({ name: 'any-other-use' }); scene.add(d1, d2);
21	  setOpacity(d2, 0.28);   // bóng: cùng cỡ tờ thật, mờ + viền nét đứt ở lớp phủ
22	  const hand = [hm.person.position.x + 0.35, 0.62, hm.person.position.z + 0.15];
23	  const [land0, land1] = S.dollar1.place;
24	
25	  function frame(t) {
26	    const pose = CAM.apply(t), cw = pose.chart, cam = CAM.cam;
27	    modeLook(scene, floor, cw);
28	    // thanh: chưa có gì trên sàn; trồi lên từ dưới sàn ngay khi tờ đô la tới chỗ (0,25 s), rồi dâng tới độ cao lãi
29	    const up = ease(t, land1 - 0.1, land1 + 0.15), H = -0.12 + (0.12 + Math.max(0.06, kf(S.bar, t) * PER_PCT)) * up;
30	    beam.position.set(BX, H, 0); beam.visible = up > 0.01; beam.userData.checks.value = +kf(S.bar, t).toFixed(3);
31	    // tờ 1: hiện trong tay Tessa → bay vòng trước mặt nhà, ĐỨNG trên mặt thanh (cạnh dưới chạm thanh), cưỡi lên theo thanh
