1	// Mốc V · LÕI "một thế giới, hai chế độ máy quay" (D-010).
2	//  - Máy quay: tư thế đặt tên (scene khai báo toạ độ), ĐỘNG TÁC HỮU HẠN giữa hai nhịp lấy từ spine.moves
3	//    {verb: push|pull|pan|mode, from, to, t0, t1, reason, sound}. Ngoài cửa sổ động tác máy quay ĐỨNG YÊN (quy tắc 2).
4	//  - Trọng số chế độ đồ thị chartW ∈ [0,1] nội suy theo tư thế (pose.chart = 0 thế giới, 1 đồ thị) — quy tắc 1 kiểm qua nhật ký.
5	//  - Lớp phủ 2D: chữ sắc ở thiết kế 1920×1080, vẽ ở độ phân giải bất kỳ; mọi chữ được ghi vào nhật ký (hộp, cỡ px, độ mờ, loại).
6	//    Loại 'number' / 'compare' chỉ hợp lệ khi chartW ≥ 0,95 — vi phạm ghi vào log.violations (quy tắc 1).
7	//  - Lớp bắt buộc (quy tắc 5): ILLUSTRATIVE, "US only · history, not a forecast", nguồn, đối trọng — chữ 48 px trên nền mờ, vị trí cố định.
8	import * as THREE from 'three';
9	export const clamp = (x, a = 0, b = 1) => Math.min(b, Math.max(a, x));
10	export const lin = (t, a, b) => (b <= a ? (t >= a ? 1 : 0) : clamp((t - a) / (b - a)));
11	export const ease = (t, a, b) => { const x = lin(t, a, b); return x * x * (3 - 2 * x); };
12	export const easeOut = (t, a, b) => 1 - Math.pow(1 - lin(t, a, b), 3);
13	export const mix = (a, b, x) => a + (b - a) * x;
14	export function rgba(hex, a) { const n = parseInt(hex.slice(1, 7), 16); return `rgba(${n >> 16},${(n >> 8) & 255},${n & 255},${a})`; }
15	export const C = { bg: '#0E1116', surface: '#171B22', grid: '#2A303B', ink: '#F2F4F7', muted: '#9AA4B2', accent: '#4C8DFF', warn: '#F2B441', costlier: '#C72323', cushion: '#269783', chrome: '#C9D1DC' };
