20	// ------------------------------------------------------------------ máy quay
21	export function Camera(poses, moves, aspect = 16 / 9) {
22	  const cam = new THREE.PerspectiveCamera(35, aspect, 0.1, 400);
23	  const P = (name) => { const p = poses[name]; if (!p) throw new Error('pose ' + name); return p; };
24	  const lerpPose = (a, b, x) => ({ pos: a.pos.map((v, i) => mix(v, b.pos[i], x)), tgt: a.tgt.map((v, i) => mix(v, b.tgt[i], x)),
25	    fov: Math.exp(mix(Math.log(a.fov), Math.log(b.fov), x)), chart: mix(a.chart || 0, b.chart || 0, x) });
26	  // F-1 (opt-in, move.style === 'fly'; mặc định 'dissolve' = lerpPose ở trên, KHÔNG đổi): máy quay ĐI THẬT từ tư thế này sang tư thế kia.
27	  //  - vị trí + điểm nhìn theo đường cong bậc hai qua tư thế `via` (nếu có) ở x = 0,5 — máy đi ngang qua vật thế giới, không trượt thẳng;
28	  //  - dolly-zoom: chiều cao khung ở điểm nhìn h = 2·d·tan(fov/2) nội suy log giữa hai tư thế, fov = 2·atan(h / 2d) theo khoảng cách thật
29	  //    → lại gần thì góc rộng (thị sai khi đi qua vật), lùi xa thì tiêu cự dài ≈ trực giao ở tư thế đồ thị (fov của tư thế đích ở x = 1);
30	  //  - chartW chỉ dâng ở nửa cuối khi vào đồ thị (rời đồ thị: rơi ở nửa đầu) → cổng số (chartW ≥ 0,95, quy tắc 1) chỉ mở khi đã chính diện.
31	  const H = (p) => 2 * Math.hypot(...p.pos.map((v, i) => v - p.tgt[i])) * Math.tan(p.fov * Math.PI / 360);
32	  const bez = (a, v, b, x) => a.map((p, i) => { const c = v ? 2 * v[i] - (p + b[i]) / 2 : (p + b[i]) / 2; return (1 - x) * (1 - x) * p + 2 * (1 - x) * x * c + x * x * b[i]; });
33	  function flyPose(a, b, v, x) {
34	    const pos = bez(a.pos, v && v.pos, b.pos, x), tgt = bez(a.tgt, v && v.tgt, b.tgt, x), d = Math.hypot(...pos.map((p, i) => p - tgt[i]));
35	    const h = Math.exp(mix(Math.log(H(a)), Math.log(H(b)), x)), ca = a.chart || 0, cb = b.chart || 0;
36	    return { pos, tgt, fov: 2 * Math.atan(h / (2 * d)) * 180 / Math.PI, chart: mix(ca, cb, cb >= ca ? ease(x, 0.5, 1) : ease(x, 0, 0.5)), fly: true };
37	  }
38	  const ms = [...moves].sort((a, b) => a.t0 - b.t0);
39	  function poseAt(t) {
40	    let cur = P(ms.length ? ms[0].from : Object.keys(poses)[0]);
41	    for (const m of ms) {
42	      if (t < m.t0) break;
43	      cur = t >= m.t1 ? P(m.to) : m.style === 'fly' ? flyPose(P(m.from), P(m.to), m.via ? P(m.via) : null, ease(t, m.t0, m.t1)) : lerpPose(P(m.from), P(m.to), ease(t, m.t0, m.t1));
44	      if (t < m.t1) break;
45	    }
46	    return cur;
47	  }
48	  return {
49	    cam, poseAt, flyPose,
50	    apply(t) {
51	      const p = poseAt(t); cam.fov = p.fov; cam.position.set(...p.pos); cam.lookAt(...p.tgt); cam.updateProjectionMatrix(); cam.updateMatrixWorld();
52	      return p;
53	    },
54	    moving(t) { return ms.some((m) => t > m.t0 && t < m.t1); },
55	  };
56	}
