68	//              lớp bắt buộc dọc của nhà máy: móc, ILLUSTRATIVE + "US only · history, not a forecast" trên MỌI khung có số, đối trọng xoay 3 s.
69	// CK.dither    0 tắt · 1 dither trong shader (material.dithering của three: nhiễu trước khi lượng tử 8 bit) · 2 (mặc định) = 1 + hạt nhiễu
70	//              ±4 mã CỐ ĐỊNH theo ô 2×2 ở điểm tối của khung ghép (darkDither; chỉ khi render, không ở trang kiểm) — chống banding gradient tối (checks F08).
71	// CK.mode (C5 ep005, chẩn đoán checks V11): 'graphics3d' = chỉ hình 3D của lớp 'graphics' (không nét lớp phủ); 'graphics2d' = chỉ nét/tô của lớp phủ
72	//              (không 3D) — tách va chạm chữ×hình 3D khỏi chữ×nét 2D. Khung render (mode 'all') không đổi.
73	export const CK = { on: false, mode: 'all', ids: null, claims: null, freezeCam: null, lastCam: null, view: null, dither: 2, shapes3d: [] };
74	export const VSAFE = { x0: 72, y0: 200, x1: 1008, y1: 1600 }, VFLOOR = 56, VZONE = { y0: 430, y1: 1410 };   // = qc.py SAFE['v'], FLOOR['v']
75	// C5 ep005 (checks V03): vùng an toàn 90 % của khung ngang (x 96–1824, y 54–1026). Chữ cảnh (không phải chrome) tràn ra ≤ NUDGE.full px được đẩy
76	// trọn vào trong; tràn NUDGE.full…NUDGE.max px: lực đẩy giảm tuyến tính về 0 (chữ đang bay ra khỏi khung đi ra liên tục, không nhảy); o.safe === false: tắt.
77	export const SAFE_H = { x0: 96, y0: 54, x1: 1824, y1: 1026 }, NUDGE = { full: 60, max: 120, margin: 2 };
78	// Lớp bắt buộc ngang: mép phải huy hiệu, đường chân chữ dòng dưới (mực của phần dưới chân chữ nằm trong vùng an toàn), nhãn gốc tính tiền cấp khung (S09, K3.3)
79	export const CHROME_H = { right: 1800, base: 1006, base2: 936, top: 108 };
80	export const BASIS_LABEL = { nominal: 'All $ in dollars of the day', real: "All $ in today's dollars" };
81	const TAG_RE = /^ILLUSTRATIVE$|history, not a forecast/;
82	const lumHex = (hex) => { const n = parseInt(String(hex).slice(1, 7), 16), f = (c) => { c /= 255; return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
83	  return 0.2126 * f(n >> 16) + 0.7152 * f((n >> 8) & 255) + 0.0722 * f(n & 255); };
84	export const contrastHex = (a, b) => { const x = lumHex(a), y = lumHex(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
85	const r1 = (v) => +(+v).toFixed(1);
