88	// khoảng claim trong một chuỗi: display (có chữ số) xuất hiện nguyên vẹn, không dính chữ/số hai bên; dài trước, không chồng nhau → [{id, i, d}]
89	export function claimSpans(s, claims) {
90	  const out = [];
91	  const list = [...(claims || [])].filter((c) => /\d/.test(String(c.display ?? ''))).sort((a, b) => String(b.display).length - String(a.display).length);
92	  for (const c of list) {
93	    const d = String(c.display);
94	    for (let i = s.indexOf(d); i >= 0; i = s.indexOf(d, i + 1)) {
95	      const pre = s[i - 1], post = s[i + d.length], post2 = s[i + d.length + 1];
96	      if (pre && /[\w.,]/.test(pre)) continue;
97	      if (post && (/\w/.test(post) || (/[.,]/.test(post) && post2 && /\d/.test(post2)))) continue;
98	      if (out.some((m) => i < m.i + m.d.length && m.i < i + d.length)) continue;
99	      out.push({ id: c.id, i, d });
100	    }
101	  }
102	  return out.sort((a, b) => a.i - b.i);
103	}
