106	export function Overlay(canvas, res) {
107	  const V = CK.view && CK.view.orient === 'v' ? CK.view : null;
108	  const S = V ? res / 1920 : res / 1080;
109	  canvas.width = Math.round((V ? 1080 : 1920) * S); canvas.height = Math.round((V ? 1920 : 1080) * S);
110	  // khung dọc: cửa sổ của mặt phẳng thiết kế 1920×1080 — rộng 1080/vs, gốc (vx0, vy0); thiết kế (x, y) → dọc ((x − vx0)·vs, (y − vy0)·vs)
111	  const vs = V ? (V.s || 1) : 1, vx0 = V ? 960 - 540 / vs : 0, vy0 = V ? 540 - (V.cy ?? (VZONE.y0 + VZONE.y1) / 2) / vs : 0;
112	  const ctx = canvas.getContext('2d');
113	  let log = null, chartW = 0, camera = null, seq = 0, inText = false, bgDraw = false, vc = null;
114	  // khung dọc (C5 ep005): chữ cảnh KHÔNG vẽ ngay mà vào hàng vq (cùng các lớp phủ cả khung vẽ sau chúng, để giữ thứ tự tối dần) → finish() xếp chỗ
115	  // (layoutV: không cặp hộp chữ nào giao nhau) rồi mới vẽ
116	  let vq = [];
117	  const base = () => ctx.setTransform(S * vs, 0, 0, S * vs, -vx0 * S * vs, -vy0 * S * vs);
118	  const proj = new THREE.Vector3();
119	  // F-2: mọi nét stroke (moveTo/lineTo) trên lớp phủ → log.lines {n: thứ tự vẽ, a, w, seg: [[x0,y0,x1,y1]…]} ở toạ độ thiết kế 1920×1080
120	  // (cả nét scene.js vẽ thẳng bằng O.ctx); sfx_labels.py kiểm đường cắt chữ. Đường cong/arc và đường 3D không ghi. Không đổi điểm ảnh.
121	  let path = [], pen = null, pts = [];
122	  const dz = (x, y) => { const m = ctx.getTransform(), k = S * vs; return [(m.a * x + m.c * y + m.e) / k + vx0, (m.b * x + m.d * y + m.f) / k + vy0]; };
123	  const raw = { beginPath: ctx.beginPath.bind(ctx), moveTo: ctx.moveTo.bind(ctx), lineTo: ctx.lineTo.bind(ctx), stroke: ctx.stroke.bind(ctx) };
124	  // CHECKS: lớp nào được vẽ (mode 'all' = mọi thứ, như khi render)
125	  const draws = (isText) => { const m = CK.mode; if (m === 'all') return true; if (m === 'text' || m === 'glyph' || m === 'only') return isText; if (m === 'graphics' || m === 'graphics2d') return !isText && !bgDraw; if (m === 'graphics3d') return false; return !isText; };
126	  const bbox = (P) => [Math.min(...P.map((p) => p[0])), Math.min(...P.map((p) => p[1])), Math.max(...P.map((p) => p[0])), Math.max(...P.map((p) => p[1]))];
127	  const shapeObj = (o, n = seq++) => { const id = 's' + n; log.objects.push({ id, n, kind: 'shape', key: o.key || id, sig: `${o.role}|${o.tag}|${(o.box || []).map(Math.round)}|${o.fill || ''}${o.stroke || ''}`, panel: null, chart: null, ...o }); };
128	  ctx.beginPath = () => { path = []; pen = null; pts = []; raw.beginPath(); };
129	  ctx.moveTo = (x, y) => { pen = dz(x, y); pts.push(pen); raw.moveTo(x, y); };
130	  ctx.lineTo = (x, y) => { const p = dz(x, y); if (pen) path.push([...pen, ...p].map((v) => +v.toFixed(1))); pen = p; pts.push(p); raw.lineTo(x, y); };
131	  ctx.stroke = (...a) => {
132	    if (log && !a.length && path.length && ctx.globalAlpha > 0.01 && !inText) {
133	      const n = seq++; log.lines.push({ n, a: +ctx.globalAlpha.toFixed(3), w: +ctx.lineWidth.toFixed(1), seg: path });
134	      if (CK.on) { const P = path.flatMap((g) => [[g[0], g[1]], [g[2], g[3]]]);
135	        shapeObj({ tag: 'line', role: 'line', stroke: hexOf(ctx.strokeStyle), fill: null, opacity: +ctx.globalAlpha.toFixed(3), box: bbox(P).map(r1), vertices: path.length + 1 }, n); }
136	    }
137	    if (draws(inText)) raw.stroke(...a);
138	  };
139	  for (const k of ['fill', 'fillRect', 'strokeRect', 'fillText', 'strokeText', 'drawImage']) {
140	    const f = ctx[k].bind(ctx);
141	    ctx[k] = (...a) => {
142	      const full = k === 'fillRect' && a[2] * a[3] >= 0.9 * 1920 * 1080;   // lớp phủ cả khung (tối dần, ident) = nền
143	      const b0 = bgDraw; if (full) bgDraw = true;
144	      if (CK.on && log && !inText && !bgDraw && ctx.globalAlpha > 0.01 && (k === 'fill' || k === 'fillRect')) {
145	        const P = k === 'fillRect' ? [dz(a[0], a[1]), dz(a[0] + a[2], a[1] + a[3])] : pts;
146	        if (P.length) shapeObj({ tag: k === 'fill' ? 'path' : 'rect', role: 'mark', fill: hexOf(ctx.fillStyle), stroke: null, opacity: +ctx.globalAlpha.toFixed(3), box: bbox(P).map(r1) });
147	      }
148	      if (draws(inText)) {
149	        if (full && V) vq.push({ op: 'fill', style: ctx.fillStyle, alpha: ctx.globalAlpha });   // dọc: phủ cả khung dọc — hoãn tới finish(), sau các chữ vẽ trước nó
150	        else f(...a);
151	      }
152	      bgDraw = b0;
153	    };
154	  }
155	  const projBox = (P) => bbox(P.map(([x, y, z]) => { proj.set(x, y, z ?? 0).project(camera); return [(proj.x + 1) * 960, (1 - proj.y) * 540]; }));
156	  const vmap = (b) => [(b[0] - vx0) * vs, (b[1] - vy0) * vs, (b[2] - vx0) * vs, (b[3] - vy0) * vs];
157	  // dọc: chữ ≥ 56 px, xuống dòng khi rộng hơn vùng an toàn, đẩy vào vùng (nội dung: VZONE; chrome trực tiếp: VSAFE) → {px, lines, x, y, box}
158	  function vfit(s, x, y, px, o, wfont) {
159	    let p = px; const raised = p * vs < VFLOOR - 1e-6; if (raised) p = VFLOOR / vs;
160	    ctx.font = `${wfont} ${p}px Inter`;
161	    const pad = o.plate ? p * 0.32 : 0, room = (VSAFE.x1 - VSAFE.x0) / vs - 2 * pad, mw = (q) => ctx.measureText(q).width;
162	    let lines = [s];
163	    if (mw(s) > room && s.includes(' ')) { lines = []; let cur = ''; for (const w of s.split(' ')) { const tr = cur ? cur + ' ' + w : w; if (cur && mw(tr) > room) { lines.push(cur); cur = w; } else cur = tr; } if (cur) lines.push(cur); }
164	    const lh = p * 1.18, ws = lines.map(mw), W = Math.max(...ws);
165	    const xl = (w) => (o.align === 'center' ? x - w / 2 : o.align === 'right' ? x - w : x);
166	    let box = [Math.min(...ws.map(xl)), y - (lines.length - 1) * lh - p * 0.78, Math.max(...ws.map((w) => xl(w) + w)), y + p * 0.24];
167	    const vb = vmap(box), Z = o.kind === 'chrome' ? VSAFE : { x0: VSAFE.x0, y0: VZONE.y0, x1: VSAFE.x1, y1: VZONE.y1 }, pv = pad * vs;
168	    let dx = 0, dy = 0;
169	    if (vb[0] - pv < Z.x0) dx = Z.x0 - (vb[0] - pv); else if (vb[2] + pv > Z.x1) dx = Z.x1 - (vb[2] + pv);
170	    if (vb[1] - pv < Z.y0) dy = Z.y0 - (vb[1] - pv); else if (vb[3] + pv > Z.y1) dy = Z.y1 - (vb[3] + pv);
