      if (cw) { vt(cw.text, 540, yb - 68 * hl, VFLOOR, { align: 'center', color: C.ink }); L.tags.push('CW:' + cw.id); }
      if (basis) { vt(basis, 540, yb - 68 * (hl + cl), VFLOOR, { align: 'center', w: 600, color: C.chrome }); L.tags.push('BASIS'); }
