export function gesture(hm, t, G = []) {
  let lean = 0, arm = 0, nod = 0, side = 1;
  for (const g of G) {
    const a = ease(t, g.t - 0.12, g.t + 0.28) * (1 - ease(t, g.t + (g.hold ?? 1.2), g.t + (g.hold ?? 1.2) + 0.45));
