    if (g.kind === 'arm') { if (a > arm) { arm = a; side = s; } lean = Math.max(lean, 0.35 * a); }
    else if (g.kind === 'lean') { if (a > lean) side = s; lean = Math.max(lean, a); }
    else nod = Math.max(nod, a);
  }
  const p = hm.person, h = hm.h;
