export function seg2(O, x0, y0, x1, y1, color, a, lw = 4, dash = null) {
  if (a <= 0.01) return; const c = O.ctx; c.save(); c.globalAlpha = a; c.strokeStyle = color; c.lineWidth = lw; if (dash) c.setLineDash(dash);
