export const TRK = { req: '#9AA4B2', dark: '#343A44', warn: '#F2B441', ink: '#F2F4F7', empty: '#2A303B' };
export function TrackC4({ n = 180, cols = 12, spare = 2, tile = 0.34, gap = 0.08, th = 0.07, slab = 0.075, SG = 0.03, SF = 0.86, DROP = 1.3, name = 'tessa' } = {}) {
