  const hide = new THREE.Matrix4().makeScale(0, 0, 0), cl = (x) => Math.min(1, Math.max(0, x)), sm = (u) => u * u * (3 - 2 * u);
  tiles.userData.checks = { role: 'mark', series: name, key: `track-${name}-tiles` };
