// ================================================================ V4 adapted: thẻ hai khoản vay (B02–B03, B33) — mặt tối viền ink-muted, chữ ở lớp phủ (đồ thị)
export function OfferCard(scene, { x, y, z = 0, w = 1.7, h = 0.66 } = {}) {
