    wC0: { pos: [-8.6, 3.0, 9.6], tgt: [-0.6, 1.5, 0], fov: 40, chart: 0 },
    cC: { pos: [2.2, 3.0, 26], tgt: [2.2, 3.0, 0], fov: 20.6, chart: 1 },
    wRow: { pos: [-7.4, 2.9, 10.4], tgt: [1.8, 1.2, -0.8], fov: 46, chart: 0 },
