    cD: { pos: [2.2, 3.0, 26], tgt: [2.2, 3.0, 0], fov: 20.6, chart: 1 },
    wEnd: { pos: [-7.6, 2.6, 7.6], tgt: [-2.4, 1.0, 0], fov: 38, chart: 0 },
