        label(O, `typical stack ${usd}`, 960, 268, { align: 'center', kind: 'number', alpha: ok * show(t, tagAt[k], k === 2 ? b.e4.gap - 0.1 : nx), claims: [cu] });
        log.roi[['e1.fifteen', 'e2.fourteen', 'e3.twenty'][k]] = [500, 150, 1420, 290];
