    const old = b.a2.finish - 0.05;
    label(O, `pay ${D('pay15_now')} on the ${D('term_long')}: ${D('months_at_pay15_now')}`, 960, 205, { align: 'center', kind: 'number', alpha: ok * show(t, b.a1.ends, old),
